package com.gymmind.membership.application; import com.gymmind.membership.domain.model.PaymentRecord; import java.math.BigDecimal; public record PaymentRecordView(Long id,Long tenantId,Long orderId,BigDecimal amount,String currency,String reference,String paymentMethod){public static PaymentRecordView from(PaymentRecord p){return new PaymentRecordView(p.getId(),p.getTenantId(),p.getOrderId(),p.getAmount(),p.getCurrency(),p.getReference(),p.getPaymentMethod());}}
